import{_ as t,c as o,o as a,ae as r}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse(`{"title":"Create Cart Rule Coupon","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"create","title":"Create Cart Rule Coupon","description":"Add a single coupon code to a cart rule.","query":"curl -X POST \\"https://your-domain.com/api/admin/marketing/cart-rules/47/coupons\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d '{\\n    \\"code\\": \\"QALIVE99\\",\\n    \\"usage_limit\\": 0,\\n    \\"usage_per_customer\\": 0,\\n    \\"expired_at\\": \\"2026-12-31\\"\\n  }'\\n","variables":"{}\\n","response":"{\\n  \\"id\\": 22,\\n  \\"cartRuleId\\": 47,\\n  \\"code\\": \\"QALIVE99\\",\\n  \\"usageLimit\\": 0,\\n  \\"usagePerCustomer\\": 0,\\n  \\"timesUsed\\": 0,\\n  \\"type\\": 1,\\n  \\"isPrimary\\": false,\\n  \\"expiredAt\\": \\"2026-12-31\\",\\n  \\"createdAt\\": \\"2026-06-09T13:48:29+05:30\\",\\n  \\"updatedAt\\": \\"2026-06-09T13:48:29+05:30\\"\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/marketing/promotions/cart-rule-coupons-create.md","filePath":"api/rest-api/admin/marketing/promotions/cart-rule-coupons-create.md"}`),d={name:"api/rest-api/admin/marketing/promotions/cart-rule-coupons-create.md"};function n(i,e,s,c,l,u){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="create-cart-rule-coupon" tabindex="-1">Create Cart Rule Coupon <a class="header-anchor" href="#create-cart-rule-coupon" aria-label="Permalink to &quot;Create Cart Rule Coupon&quot;">​</a></h1><p>Adds a single coupon code to a cart rule — the <strong>Add Coupon</strong> action on the <strong>Coupons</strong> tab of the admin <strong>Marketing → Promotions → Cart Rules</strong> screen.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>New here? Read the <a href="/api/rest-api/admin/marketing/promotions/cart-rule-coupons/">Cart Rule Coupons overview</a> for what these coupons do and how they relate to a cart rule.</p></div><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/marketing/cart-rules/{cartRuleId}/coupons</code></td><td>POST</td></tr></tbody></table><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Requires an admin Bearer token and the <code>marketing.promotions.cart_rules.create</code> permission.</li><li>The created coupon is a <strong>secondary</strong> code (<code>type</code> <code>1</code>, <code>isPrimary</code> <code>false</code>). The rule&#39;s own primary code is managed on the cart rule itself.</li><li>Omitted <code>usage_limit</code> / <code>usage_per_customer</code> / <code>expired_at</code> inherit the parent rule&#39;s settings.</li><li>Returns the full coupon payload.</li></ul><h2 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>code</code></td><td>string</td><td>yes</td><td>Coupon code; must be unique</td></tr><tr><td><code>usage_limit</code></td><td>int</td><td>no</td><td>Total redemptions allowed (<code>0</code> = unlimited); inherits the rule when omitted</td></tr><tr><td><code>usage_per_customer</code></td><td>int</td><td>no</td><td>Redemptions per customer (<code>0</code> = unlimited); inherits the rule when omitted</td></tr><tr><td><code>expired_at</code></td><td>string</td><td>no</td><td>Expiry date (<code>YYYY-MM-DD</code>); inherits the rule when omitted</td></tr></tbody></table>',9)]))}const m=t(d,[["render",n]]);export{h as __pageData,m as default};
